<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {useRouter} from 'vue-router'
import {NCard,NButton,NInput,NSelect,NAlert,NTag,NSkeleton} from 'naive-ui'
import {api,uncertainMessage} from '../../api'
import {useGmWorkspace} from '../../stores/gm/useGmWorkspace'
import PlayerShortcuts from '../../components/PlayerShortcuts.vue'
const gm=useGmWorkspace(),router=useRouter(),query=ref(''),mode=ref('account'),data=ref<any>(null),error=ref(''),busy=ref(false)
const modes=[{label:'账号 / UID',value:'account'},{label:'角色名 / 编号',value:'role'}]
const destinations:Record<string,string>={support:'/players/support',operations:'/system/audit',batches:'/rewards/batches',schedules:'/rewards/schedules',infrastructure:'/system/maintenance'}
const labels:Record<string,string>={open:'待处理',in_progress:'处理中',uncertain:'待核对',executing:'提交中',dispatching:'处理中',failed:'失败',needs_review:'待核对',needs_attention:'需处理',paused:'已暂停',active:'今日计划',unknown:'未知',unavailable:'不可用',ok:'需核验'}
const total=computed(()=>data.value?.sections.reduce((sum:number,s:any)=>sum+s.items.length,0)||0)
let alive=true,timer:ReturnType<typeof setInterval>|undefined
function search(){void router.push({path:'/players',query:{q:query.value,mode:mode.value}})}
function openTarget(value:{uid:number,charac_no:number}){void router.push(value.charac_no?'/characters/'+value.charac_no:'/players/'+value.uid)}
async function load(){if(busy.value)return;busy.value=true;error.value='';try{const r=await api('/workbench');if(alive)data.value=r}catch(e){if(alive)error.value=uncertainMessage(e)}finally{if(alive)busy.value=false}}
function jump(item:any){void router.push({path:item.path,query:item.query})}
onMounted(()=>{void gm.activate('overview');void load();timer=setInterval(()=>{if(!document.hidden)void load()},60000)})
onUnmounted(()=>{alive=false;if(timer)clearInterval(timer)})
</script>
<template><div class="gm-workspace player-home">
 <header class="home-heading"><div><span class="home-eyebrow">ARAD / GM WORKSPACE</span><h1>玩家工作台</h1><p>从玩家出发，核对存档、处理问题与发放奖励。</p></div><NButton secondary @click="gm.go('mail')">创建奖励草稿</NButton></header>
 <NCard :bordered="false" class="home-search-card"><form class="home-player-search" @submit.prevent="search"><NSelect v-model:value="mode" :options="modes" aria-label="搜索类型"/><NInput v-model:value="query" clearable :placeholder="mode==='role'?'角色名或角色编号':'账号名或 UID'" aria-label="查找玩家"/><NButton type="primary" attr-type="submit">查找玩家</NButton></form></NCard>
 <PlayerShortcuts :revision="gm.playerRevision" :busy="gm.busy||!!gm.pendingId" :current="gm.currentPlayerTarget" @choose="openTarget" @changed="gm.playerRevision++" @expired="gm.clearSession"/>
 <NAlert v-if="gm.pendingId" type="warning" title="当前浏览器还有一笔普通奖励待核对"><code>{{gm.pendingId}}</code><NButton size="small" @click="gm.inspectOperation(gm.pendingId)">查询原操作</NButton></NAlert>
 <div class="home-inbox-heading"><div><h2>统一待办 <NTag v-if="data" size="small">{{total}}{{data.sections.some((s:any)=>s.has_more)?'+':''}}</NTag></h2><small>跨工作流记录 · {{data?'核对于 '+new Date(data.checked_at*1000).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'正在读取'}} · 北京时间</small></div><NButton size="small" :loading="busy" @click="load">刷新待办</NButton></div>
 <NAlert v-if="error" type="warning" :show-icon="false">{{error}}。现有内容是上次快照，不能据此判断任务完成。</NAlert>
 <div v-if="!data&&busy" class="home-work-grid"><NSkeleton v-for="n in 4" :key="n" height="200px"/></div>
 <div v-if="data" class="home-work-grid"><NCard v-for="section in data.sections" :key="section.key" :bordered="false" :title="section.label"><template #header-extra><NButton text size="small" @click="router.push(destinations[section.key]||'/home')">全部 {{section.items.length}}{{section.has_more?'+':''}} →</NButton></template><div v-if="section.items.length" class="home-inbox-items"><button v-for="item in section.items.slice(0,4)" :key="item.id" class="home-inbox-row" @click="jump(item)"><span><strong>{{item.title}}</strong><small v-if="item.uid||item.target_uid">UID {{item.uid||item.target_uid}}<span v-if="item.charac_no"> · 角色 #{{item.charac_no}}</span></small><small v-else>{{item.id}}</small></span><NTag size="small" :type="section.key==='support'?'default':'warning'">{{labels[item.status]||item.status}}</NTag></button></div><p v-else class="home-empty">本次查询没有待处理记录</p><small v-if="section.items.length>4" class="muted">另有 {{section.items.length-4}} 条{{section.has_more?'以上':''}}记录，请进入列表处理。</small></NCard></div>
 <div v-if="data" class="home-status-grid"><NCard :bordered="false"><small>GM 管理库</small><strong>{{data.management_backup.state==='ok'?'已读取备份证据':'备份证据待核对'}}</strong><NButton text size="small" @click="gm.go('maintenance')">备份与恢复记录 →</NButton></NCard><NCard :bordered="false"><small>游戏存档</small><strong>{{data.game_backup.worker.configured?'备份执行器已配置':'未配置或状态未知'}}</strong><NButton text size="small" @click="gm.go('game-backups')">备份 / 异地副本 / 隔离演练 →</NButton></NCard><NCard :bordered="false"><small>活动运营</small><strong>礼包版本、批次与去重</strong><NButton text size="small" @click="gm.go('campaigns')">进入活动 →</NButton></NCard></div>
 <small class="muted">{{data?.note||'数据库提交、领取标记和客户端反馈分别核对。'}}{{data?.task_health.state==='unknown'?'任务健康状态未知，请进入运维诊断核对。':''}}</small>
</div></template>
<style scoped>
.player-home{display:grid;gap:18px}.home-heading,.home-inbox-heading{display:flex;justify-content:space-between;align-items:center;gap:16px}.home-heading h1{margin:4px 0;font-size:25px;letter-spacing:-.04em}.home-heading p{margin:0;color:var(--text-secondary)}.home-eyebrow{color:var(--amber-text);font-size:10px;letter-spacing:.2em}.home-player-search{display:grid;grid-template-columns:150px minmax(0,1fr) auto;gap:10px}.home-work-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.home-work-grid>.n-card:last-child:nth-child(odd){grid-column:1/-1}.home-inbox-heading h2{margin:0 0 4px;display:flex;align-items:center;gap:8px}.home-inbox-heading small{color:var(--text-secondary)}.home-inbox-items{display:grid}.home-inbox-row{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;padding:12px 0;text-align:left;border:0;border-bottom:1px solid var(--border-color);border-radius:0;background:transparent}.home-inbox-row:first-child{padding-top:0}.home-inbox-row>span{min-width:0}.home-inbox-row strong{display:block;font-size:13px;font-weight:550;overflow-wrap:anywhere}.home-inbox-row small{display:block;margin-top:4px;font-size:11px;color:var(--text-secondary);overflow-wrap:anywhere}.home-empty{color:var(--text-secondary);padding:16px 0}.home-status-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.home-status-grid strong{display:block;margin:6px 0 12px;font-size:14px}.home-status-grid small{color:var(--text-secondary)}code{overflow-wrap:anywhere}.n-alert .n-button{margin-left:12px}@media(max-width:700px){.home-work-grid,.home-status-grid{grid-template-columns:1fr}.home-heading{align-items:start}.home-heading h1{font-size:22px}.home-heading p{font-size:12px}.home-player-search{grid-template-columns:1fr auto}.home-player-search>.n-select{grid-column:1/-1}.home-eyebrow{display:none}.home-heading>.n-button{font-size:12px}.player-home{gap:12px}}
</style>
